      fmt.Println("System Default: "+env.arch+"-bit.")
      fmt.Println("Currently Configured: "+a+"-bit.")
    case "proxy":
      if detail == "" {
        fmt.Println("Current proxy: "+env.proxy)
      } else {
        env.proxy = detail
        saveSettings()
      }
    //case "update": update()
    case "node_mirror": setNodeMirror(detail)
    case "npm_mirror": setNpmMirror(detail)
    default: help()
  }
}

