	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	data := struct {
		ContentType   string
		Content       html_template.HTML
		Filename      string
		Url           string
		ContentLength uint64
	}{
		contentType,
		content,
		filename,
		r.URL.String(),
		contentLength,
	}

	if err := tmpl.Execute(w, data); err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

}

