	switch s := step.(type) {
	case IteratorStep:
		return s.BuildIterator(qs, ns)
	case PathStep:
		p, err := s.BuildPath(qs, ns)
		if err != nil {
			return nil, err
		}
		return NewDocumentIterator(qs, p), nil
	}
	return nil, errors.New("must execute a IteratorStep or PathStep")

